// The shared conformance fixtures, generated by the Rust reader's tests;
// see fixtures/packs/README.md.
var fixtures = filepath.Join("..", "..", "fixtures", "packs")

type manifestLimits struct {
	MaxPackBytes    uint64 `json:"max_pack_bytes"`
	MaxDecodedBytes uint64 `json:"max_decoded_bytes"`
}

func (l *manifestLimits) limits() Limits {
	if l == nil {
		return Limits{}
	}
	return Limits{MaxPackBytes: l.MaxPackBytes, MaxDecodedBytes: l.MaxDecodedBytes}
}

type manifestRead struct {
	Op    string          `json:"op"`
	Rule  string          `json:"rule"`
	Plane string          `json:"plane"`
	Type  string          `json:"type"`
	ID    json.RawMessage `json:"id"`
	Layer int32           `json:"layer"`
	CX    int64           `json:"cx"`
	CY    int64           `json:"cy"`
	X     int64           `json:"x"`
	Y     int64           `json:"y"`
	Error *Code           `json:"error"`
}

type manifestCase struct {
	File         string          `json:"file"`
	Rule         string          `json:"rule"`
	OpenLimits   *manifestLimits `json:"open_limits"`
	Open         *Code           `json:"open"`
	Reads        []manifestRead  `json:"reads"`
	VerifyLimits *manifestLimits `json:"verify_limits"`
	Verify       *Code           `json:"verify"`
}

type manifestChunk struct {
	Plane        string   `json:"plane"`
	Layer        int32    `json:"layer"`
	CX           int64    `json:"cx"`
	CY           int64    `json:"cy"`
	Palette      []string `json:"palette"`
	Objects      uint64   `json:"objects"`
	RenderSHA256 string   `json:"render_sha256"`
}

type manifestValid struct {
	File        string            `json:"file"`
	Summary     map[string]uint64 `json:"summary"`
	Meta        map[string]string `json:"meta"`
	LayerHeight *uint32           `json:"layer_height"`
	Strings     []string          `json:"strings"`
	Planes      []struct {
		ID        string `json:"id"`
		Kind      string `json:"kind"`
		ChunkSize uint16 `json:"chunk_size"`
		Document  string `json:"document"`
	} `json:"planes"`
	Zones []struct {
		Plane    string  `json:"plane"`
		ID       string  `json:"id"`
		Parent   *string `json:"parent"`
		Document string  `json:"document"`
	} `json:"zones"`
	Anchors []struct {
		Plane string `json:"plane"`
		ID    string `json:"id"`
		Layer int32  `json:"layer"`
		X     int64  `json:"x"`
		Y     int64  `json:"y"`
	} `json:"anchors"`
	Stairwells []struct {
		Plane    string `json:"plane"`
		ID       string `json:"id"`
		Document string `json:"document"`
	} `json:"stairwells"`
	Steps []struct {
		Plane     string `json:"plane"`
		Layer     int32  `json:"layer"`
		X         int64  `json:"x"`
		Y         int64  `json:"y"`
		Stairwell string `json:"stairwell"`
		Step      int    `json:"step"`
		Proto     string `json:"proto"`
	} `json:"steps"`
	Definitions []struct {
		Type     string `json:"type"`
		ID       string `json:"id"`
		Document string `json:"document"`
	} `json:"definitions"`
	Chunks []manifestChunk `json:"chunks"`
}

type manifest struct {
	Format string          `json:"format"`
	Codes  []Code          `json:"codes"`
	Valid  []manifestValid `json:"valid"`
	Cases  []manifestCase  `json:"cases"`
}

func loadManifest(t *testing.T) manifest {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(fixtures, "manifest.json"))
	if err != nil {
		t.Fatalf("the conformance fixtures are missing; run the tests from a tilewright-world checkout: %v", err)
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	var parsed manifest
	if err := decoder.Decode(&parsed); err != nil {
		t.Fatal(err)
	}
	if parsed.Format != "tilewright.pack-conformance/1" {
		t.Fatalf("manifest format %q", parsed.Format)
	}
	return parsed
}

func TestTheManifestListsEveryCode(t *testing.T) {
	if codes := loadManifest(t).Codes; !slices.Equal(codes, Codes()) {
		t.Fatalf("the manifest lists %v, this reader %v", codes, Codes())
	}
}

func codeString(code *Code) string {
	if code == nil {
		return "success"
	}
	return string(*code)
}

func outcome(err error) *Code {
	if err == nil {
		return nil
	}
	code := CodeOf(err)
	return &code
}

func (r manifestRead) textID(t *testing.T) string {
	var id string
	if err := json.Unmarshal(r.ID, &id); err != nil {
		t.Fatalf("%s: id: %v", r.Op, err)
	}
	return id
}

// run performs a single read and returns its error.
func (r manifestRead) run(ctx context.Context, t *testing.T, pack *Pack) error {
	var err error
	switch r.Op {
	case "chunk":
		_, _, err = pack.Chunk(ctx, r.Plane, r.Layer, r.CX, r.CY)
	case "string":
		id, parseErr := strconv.ParseUint(string(r.ID), 10, 32)
		if parseErr != nil {
			t.Fatal(parseErr)
		}
		_, _, err = pack.String(ctx, uint32(id))
	case "stairwell":
		_, _, err = pack.Stairwell(ctx, r.Plane, r.textID(t))
	case "stairwell_step":
		_, _, err = pack.StairwellStep(ctx, r.Plane, r.Layer, r.X, r.Y)
	case "layer_height":
		_, _, err = pack.LayerHeight(ctx)
	case "profile":
		_, err = pack.Profile(ctx)
	case "plane":
		_, _, err = pack.Plane(ctx, r.textID(t))
	case "zone":
		_, _, err = pack.Zone(ctx, r.Plane, r.textID(t))
	case "anchor":
		_, _, err = pack.Anchor(ctx, r.Plane, r.textID(t))
	case "definition":
		_, _, err = pack.Definition(ctx, r.Type, r.textID(t))
	default:
		t.Fatalf("unknown read %q", r.Op)
	}
	return err
}

func TestTheGoReaderConforms(t *testing.T) {
	ctx := context.Background()
	for _, c := range loadManifest(t).Cases {
		t.Run(c.File, func(t *testing.T) {
			pack, err := Open(ctx, filepath.Join(fixtures, c.File), c.OpenLimits.limits())
			if got := outcome(err); codeString(got) != codeString(c.Open) {
				t.Fatalf("%s: open: %s (%v), expected %s", c.Rule, codeString(got), err, codeString(c.Open))
			}
			if err != nil {
				return
			}
			defer pack.Close()
			for _, read := range c.Reads {
				err := read.run(ctx, t, pack)
				if got := outcome(err); codeString(got) != codeString(read.Error) {
					t.Errorf("%s: %s %s: %s (%v), expected %s", c.Rule, read.Op, read.Rule, codeString(got), err, codeString(read.Error))
				}
			}
			_, err = pack.Verify(ctx, c.VerifyLimits.limits())
			if got := outcome(err); codeString(got) != codeString(c.Verify) {
				t.Errorf("%s: verify: %s (%v), expected %s", c.Rule, codeString(got), err, codeString(c.Verify))
			}
		})
	}
}

// render writes a decoded chunk as fixtures/packs/README.md specifies, so
// its digest can be compared with the Rust reader's.
func render(chunk *Chunk) string {
	var output strings.Builder
	list := func(values []string) string { return strings.Join(values, " ") }
	numbers := func(count int, value func(int) int64) string {
		texts := make([]string, count)
		for i := range texts {
			texts[i] = strconv.FormatInt(value(i), 10)
		}
		return list(texts)
	}
	fmt.Fprintf(&output, "chunk_size %d\n", chunk.ChunkSize)
	fmt.Fprintf(&output, "palette %s\n", numbers(len(chunk.Palette), func(i int) int64 { return int64(chunk.Palette[i]) }))
	for _, grid := range chunk.Ground {
		fmt.Fprintf(&output, "ground %s\n", numbers(len(grid), func(i int) int64 { return int64(grid[i]) }))
	}
	fmt.Fprintf(&output, "heights %s\n", numbers(len(chunk.Heights), func(i int) int64 { return int64(chunk.Heights[i]) }))
	fmt.Fprintf(&output, "zones %s\n", numbers(len(chunk.Zones), func(i int) int64 { return int64(chunk.Zones[i]) }))
	var object func(*Object, int)
	object = func(o *Object, depth int) {
		fmt.Fprintf(&output, "object %d %d %d %d %d %d\n", depth, o.Tile, o.Proto, o.Layer, o.SubLayer, o.Z)
		if p := o.Portal; p != nil {
			if p.Kind == PortalLocation {
				fmt.Fprintf(&output, "portal location %d %d %d %d\n", p.Plane, p.Layer, p.X, p.Y)
			} else {
				fmt.Fprintf(&output, "portal anchor %d %d\n", p.Plane, p.Anchor)
			}
		}
		for _, f := range o.Fields {
			var value string
			switch f.Kind {
			case FieldNull:
				value = "null"
			case FieldBool:
				value = fmt.Sprintf("bool %t", f.Bool)
			case FieldInteger:
				value = fmt.Sprintf("integer %d", f.Integer)
			case FieldNumber:
				value = fmt.Sprintf("number %016x", mathBits(f.Number))
			case FieldString:
				value = fmt.Sprintf("string %d", f.String)
			case FieldJSON:
				value = "json " + f.JSON
			}
			fmt.Fprintf(&output, "field %d %s\n", f.Name, value)
		}
		if o.Custom != "" {
			fmt.Fprintf(&output, "custom %s\n", o.Custom)
		}
		for i := range o.Inventory {
			object(&o.Inventory[i], depth+1)
		}
	}
	for i := range chunk.Objects {
		object(&chunk.Objects[i], 0)
	}
	return output.String()
}

func countObjects(objects []Object) uint64 {
	var total uint64
	for i := range objects {
		total += 1 + countObjects(objects[i].Inventory)
	}
	return total
}

// collect gathers every value of an iterator, failing on its first error.
func collect[T any](t *testing.T, values func(func(T, error) bool)) []T {
	t.Helper()
	var all []T
	for value, err := range values {
		if err != nil {
			t.Fatal(err)
		}
		all = append(all, value)
	}
	return all
}

func TestTheValidPacksReadBackAsTheManifestLists(t *testing.T) {
	ctx := context.Background()
	for _, valid := range loadManifest(t).Valid {
		t.Run(valid.File, func(t *testing.T) {
			pack, err := Open(ctx, filepath.Join(fixtures, valid.File), Limits{})
			if err != nil {
				t.Fatal(err)
			}
			defer pack.Close()
			summary, err := pack.Verify(ctx, Limits{})
			if err != nil {
				t.Fatal(err)
			}
			counts := map[string]uint64{
				"strings": summary.Strings, "planes": summary.Planes, "zones": summary.Zones,
				"anchors": summary.Anchors, "stairwells": summary.Stairwells, "chunks": summary.Chunks,
				"definitions": summary.Definitions, "objects": summary.Objects,
			}
			if fmt.Sprint(counts) != fmt.Sprint(valid.Summary) {
				t.Errorf("summary %v, expected %v", counts, valid.Summary)
			}
			for key, expected := range valid.Meta {
				if value, ok, err := pack.Meta(ctx, key); err != nil || !ok || value != expected {
					t.Errorf("meta %s: %q %v %v", key, value, ok, err)
				}
			}
			height, stacked, err := pack.LayerHeight(ctx)
			if err != nil || stacked != (valid.LayerHeight != nil) || (stacked && height != *valid.LayerHeight) {
				t.Errorf("layer height %d %v %v", height, stacked, err)
			}
			for i, expected := range valid.Strings {
				if value, ok, err := pack.String(ctx, uint32(i+1)); err != nil || !ok || value != expected {
					t.Errorf("string %d: %q %v %v", i+1, value, ok, err)
				}
			}
			if _, ok, err := pack.String(ctx, uint32(len(valid.Strings)+1)); ok || err != nil {
				t.Errorf("a string past the last: %v %v", ok, err)
			}
			var expectedPlanes []Plane
			for _, plane := range valid.Planes {
				expectedPlanes = append(expectedPlanes, Plane(plane))
			}
			if planes := collect(t, pack.Planes(ctx)); !slices.Equal(planes, expectedPlanes) {
				t.Errorf("planes %+v, expected %+v", planes, expectedPlanes)
			}
			var zones, anchors, stairwells []string
			var planeNames []string
			for _, plane := range valid.Planes {
				planeNames = append(planeNames, plane.ID)
				for _, zone := range collect(t, pack.Zones(ctx, plane.ID)) {
					zones = append(zones, fmt.Sprintf("%s/%s/%s/%s", zone.Plane, zone.ID, zone.Parent, zone.Document))
				}
				for _, anchor := range collect(t, pack.Anchors(ctx, plane.ID)) {
					anchors = append(anchors, fmt.Sprint(anchor))
				}
				for _, stairwell := range collect(t, pack.Stairwells(ctx, plane.ID)) {
					stairwells = append(stairwells, plane.ID+"/"+stairwell.ID+"/"+stairwell.Document)
				}
			}
			var expectedZones, expectedAnchors, expectedStairwells []string
			for _, zone := range valid.Zones {
				parent := ""
				if zone.Parent != nil {
					parent = *zone.Parent
				}
				expectedZones = append(expectedZones, fmt.Sprintf("%s/%s/%s/%s", zone.Plane, zone.ID, parent, zone.Document))
			}
			for _, anchor := range valid.Anchors {
				expectedAnchors = append(expectedAnchors, fmt.Sprint(Anchor(anchor)))
			}
			for _, stairwell := range valid.Stairwells {
				expectedStairwells = append(expectedStairwells, stairwell.Plane+"/"+stairwell.ID+"/"+stairwell.Document)
			}
			for _, pair := range [][2][]string{{zones, expectedZones}, {anchors, expectedAnchors}, {stairwells, expectedStairwells}} {
				if !slices.Equal(pair[0], pair[1]) {
					t.Errorf("read %q, expected %q", pair[0], pair[1])
				}
			}
			for _, step := range valid.Steps {
				tile, ok, err := pack.StairwellStep(ctx, step.Plane, step.Layer, step.X, step.Y)
				if err != nil || !ok || tile != (StairwellTile{Stairwell: step.Stairwell, Step: step.Step, Proto: step.Proto}) {
					t.Errorf("step %+v: %+v %v %v", step, tile, ok, err)
				}
			}
			var expectedDefinitions []Definition
			for _, definition := range valid.Definitions {
				expectedDefinitions = append(expectedDefinitions, Definition(definition))
			}
			if definitions := collect(t, pack.Definitions(ctx)); !slices.Equal(definitions, expectedDefinitions) {
				t.Errorf("definitions %+v, expected %+v", definitions, expectedDefinitions)
			}
			for _, expected := range expectedDefinitions {
				if definition, ok, err := pack.Definition(ctx, expected.Type, expected.ID); err != nil || !ok || definition != expected {
					t.Errorf("definition %s/%s: %+v %v %v", expected.Type, expected.ID, definition, ok, err)
				}
			}
			var keys []string
			for _, plane := range planeNames {
				for _, layer := range collect(t, pack.Layers(ctx, plane)) {
					for _, key := range collect(t, pack.ChunkKeys(ctx, plane, layer)) {
						keys = append(keys, fmt.Sprintf("%s/%d/%d/%d", plane, layer, key.CX, key.CY))
					}
				}
			}
			var expectedKeys []string
			for _, expected := range valid.Chunks {
				expectedKeys = append(expectedKeys, fmt.Sprintf("%s/%d/%d/%d", expected.Plane, expected.Layer, expected.CX, expected.CY))
				chunk, ok, err := pack.Chunk(ctx, expected.Plane, expected.Layer, expected.CX, expected.CY)
				if err != nil || !ok {
					t.Fatalf("chunk %+v: %v %v", expected, ok, err)
				}
				var palette []string
				for _, id := range chunk.Palette {
					value, _, err := pack.String(ctx, id)
					if err != nil {
						t.Fatal(err)
					}
					palette = append(palette, value)
				}
				if !slices.Equal(palette, expected.Palette) || countObjects(chunk.Objects) != expected.Objects {
					t.Errorf("chunk %+v: palette %v, %d objects", expected, palette, countObjects(chunk.Objects))
				}
				digest := sha256.Sum256([]byte(render(chunk)))
				if hex.EncodeToString(digest[:]) != expected.RenderSHA256 {
					t.Errorf("chunk %+v renders as\n%s", expected, render(chunk))
				}
			}
			if !slices.Equal(keys, expectedKeys) {
				t.Errorf("chunk keys %v, expected %v", keys, expectedKeys)
			}
		})
	}
}

func mathBits(value float64) uint64 {
	return math.Float64bits(value)
}
